#!/usr/bin/env python3
from pathlib import Path
import json,numpy as np,pandas as pd,matplotlib.pyplot as plt
R=Path(__file__).resolve().parents[1]; D=pd.read_csv(R/'data/participants.csv'); A=pd.read_csv(R/'results/table_artifacts.csv'); J=json.loads((R/'results/analysis_results.json').read_text()); out=R/'figures';out.mkdir(exist_ok=True)
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10})
# 1 outcomes
means=D.groupby('group')[['pre_score','post_score','delayed_score']].mean(); sem=D.groupby('group')[['pre_score','post_score','delayed_score']].sem(); x=np.arange(3)
fig,ax=plt.subplots(figsize=(7.2,4.4));
for g,c,l in [('experimental','#1F4E78','Экспериментальная'),('comparison','#8C8C8C','Группа сравнения')]:ax.errorbar(x,means.loc[g],yerr=1.96*sem.loc[g],marker='o',capsize=4,lw=2,c=c,label=l)
ax.set(xticks=x,xticklabels=['Входной','Итоговый','Отложенный'],ylabel='Баллы, 0–100',title='Динамика тестовых результатов');ax.set_ylim(30,85);ax.grid(axis='y',alpha=.25);ax.legend(frameon=False);fig.text(.01,.01,'Синтетические данные; точки — средние, усы — 95% ДИ среднего.',fontsize=8,color='#555555');fig.tight_layout(rect=[0,.05,1,1]);fig.savefig(out/'01_динамика_тестов.png',dpi=220);plt.close(fig)
# 2 artifacts
q=A[A.criterion!='total_0_32'].copy(); labels=['Вопрос','Гипотеза','Источники','Дизайн','Происхождение','Воспроизводимость','Выбор модели','Рефлексия']; y=np.arange(len(q));fig,ax=plt.subplots(figsize=(7.3,5.0));ax.barh(y+.18,q.exp_mean,.34,color='#1F4E78',label='Экспериментальная');ax.barh(y-.18,q.ctrl_mean,.34,color='#A6A6A6',label='Группа сравнения');ax.set(yticks=y,yticklabels=labels,xlim=(0,4),xlabel='Средняя экспертная оценка, 0–4',title='Качество проектных артефактов');ax.invert_yaxis();ax.grid(axis='x',alpha=.2);ax.legend(frameon=False,loc='lower right');fig.text(.01,.01,'Синтетические данные; среднее двух экспертных оценок.',fontsize=8,color='#555555');fig.tight_layout(rect=[0,.04,1,1]);fig.savefig(out/'02_артефакты.png',dpi=220);plt.close(fig)
# 3 behavior
metrics=['Проверенные\nссылки','Воспроизведение','Обоснование\nмодели']; exp=[D[D.group_code==1].references_verified.sum()/D[D.group_code==1].references_total.sum(),D[D.group_code==1].reproduced.mean(),D[D.group_code==1].model_justified.mean()];ctrl=[D[D.group_code==0].references_verified.sum()/D[D.group_code==0].references_total.sum(),D[D.group_code==0].reproduced.mean(),D[D.group_code==0].model_justified.mean()];x=np.arange(3);fig,ax=plt.subplots(figsize=(7.1,4.5));ax.bar(x-.18,np.array(exp)*100,.36,color='#1F4E78',label='Экспериментальная');ax.bar(x+.18,np.array(ctrl)*100,.36,color='#A6A6A6',label='Группа сравнения');ax.set(xticks=x,xticklabels=metrics,ylabel='Доля, %',ylim=(0,105),title='Поведенческие показатели');ax.grid(axis='y',alpha=.2);ax.legend(frameon=False);fig.text(.01,.01,'Синтетические данные. Для ссылок указана доля записей; прочие показатели — доля студентов.',fontsize=8,color='#555555');fig.tight_layout(rect=[0,.05,1,1]);fig.savefig(out/'03_поведенческие_показатели.png',dpi=220);plt.close(fig)
# 4 regression forest
regs=J['regression']; names=['Качество проверки','Полнота журнала','Входной балл']; keys=['verification_quality','log_completeness','pre_score']; beta=np.array([regs[k]['beta'] for k in keys]);lo=np.array([regs[k]['boot_lo'] for k in keys]);hi=np.array([regs[k]['boot_hi'] for k in keys]);y=np.arange(3);fig,ax=plt.subplots(figsize=(7.1,3.8));ax.axvline(0,color='#444',lw=1);ax.errorbar(beta,y,xerr=[beta-lo,hi-beta],fmt='o',color='#1F4E78',capsize=4);ax.set(yticks=y,yticklabels=names,xlabel='Стандартизованный коэффициент β',title='Разведочная регрессия результата переноса');ax.invert_yaxis();ax.grid(axis='x',alpha=.2);fig.text(.01,.01,'Синтетические данные; бутстрэп-интервалы, 2000 повторов; n=27.',fontsize=8,color='#555555');fig.tight_layout(rect=[0,.06,1,1]);fig.savefig(out/'04_регрессия.png',dpi=220);plt.close(fig)
